import { randomUUID } from 'node:crypto';
import type { DatabaseSync } from 'node:sqlite';

export type JobStatus = 'queued' | 'running' | 'completed' | 'failed';

/** A row of the `jobs` table, as stored. */
export interface JobRow {
  seq: number;
  id: string;
  idempotency_key: string | null;
  status: JobStatus;
  input: string;
  steps: number;
  fail_attempts: number;
  attempts: number;
  progress_completed: number;
  result: string | null;
  error: string | null;
  run_after: number;
  lease_until: number | null;
  created_at: string;
  updated_at: string;
}

/** The job shape returned by every endpoint. */
export interface PublicJob {
  id: string;
  status: JobStatus;
  input: string;
  steps: number;
  failAttempts: number;
  attempts: number;
  progress: { completed: number; total: number };
  result: { output: string } | null;
  error: string | null;
  createdAt: string;
  updatedAt: string;
}

export interface NewJob {
  input: string;
  steps: number;
  failAttempts: number;
}

export const MAX_ATTEMPTS = 3;
export const TRANSIENT_ERROR = 'transient failure';

export function toPublicJob(row: JobRow): PublicJob {
  return {
    id: row.id,
    status: row.status,
    input: row.input,
    steps: row.steps,
    failAttempts: row.fail_attempts,
    attempts: row.attempts,
    progress: { completed: row.progress_completed, total: row.steps },
    result: row.status === 'completed' && row.result !== null ? { output: row.result } : null,
    error: row.status === 'failed' ? row.error : null,
    createdAt: row.created_at,
    updatedAt: row.updated_at,
  };
}

export function getJobRow(db: DatabaseSync, id: string): JobRow | undefined {
  return db.prepare('SELECT * FROM jobs WHERE id = ?').get(id) as unknown as JobRow | undefined;
}

export function findJobRowByKey(db: DatabaseSync, key: string): JobRow | undefined {
  return db.prepare('SELECT * FROM jobs WHERE idempotency_key = ?').get(key) as unknown as JobRow | undefined;
}

/** All jobs, newest first. */
export function listJobRows(db: DatabaseSync): JobRow[] {
  return db.prepare('SELECT * FROM jobs ORDER BY seq DESC').all() as unknown as JobRow[];
}

export function insertJobRow(db: DatabaseSync, job: NewJob, idempotencyKey: string | null): JobRow {
  const id = randomUUID();
  const now = new Date().toISOString();
  db.prepare(
    `INSERT INTO jobs (id, idempotency_key, status, input, steps, fail_attempts, attempts, progress_completed, run_after, created_at, updated_at)
     VALUES (?, ?, 'queued', ?, ?, ?, 0, 0, 0, ?, ?)`,
  ).run(id, idempotencyKey, job.input, job.steps, job.failAttempts, now, now);
  const row = getJobRow(db, id);
  if (!row) throw new Error(`inserted job ${id} not found`);
  return row;
}

