import type { NewJob } from './jobs.ts';

export interface FieldError {
  field: string;
  message: string;
}

export type ValidationResult = { ok: true; value: NewJob } | { ok: false; fields: FieldError[] };

const ALLOWED_FIELDS = new Set(['input', 'steps', 'failAttempts']);
const MAX_INPUT_LENGTH = 1000;

function readInteger(
  body: Record<string, unknown>,
  name: 'steps' | 'failAttempts',
  fallback: number,
  min: number,
  max: number,
  errors: FieldError[],
): number {
  if (!Object.hasOwn(body, name)) return fallback;
  const value = body[name];
  if (typeof value === 'number' && Number.isInteger(value) && value >= min && value <= max) return value;
  errors.push({ field: name, message: `Must be an integer from ${min} to ${max}.` });
  return fallback;
}

/** Validates a parsed JSON body for POST /api/jobs. Defaults are applied to missing optional fields. */
export function validateNewJob(body: unknown): ValidationResult {
  if (typeof body !== 'object' || body === null || Array.isArray(body)) {
    return { ok: false, fields: [{ field: 'body', message: 'Must be a JSON object.' }] };
  }
  const obj = body as Record<string, unknown>;
  const errors: FieldError[] = [];

  for (const key of Object.keys(obj)) {
    if (!ALLOWED_FIELDS.has(key)) errors.push({ field: key, message: 'Unknown field.' });
  }

  let input = '';
  if (!Object.hasOwn(obj, 'input')) {
    errors.push({ field: 'input', message: 'Required.' });
  } else if (typeof obj.input !== 'string') {
    errors.push({ field: 'input', message: 'Must be a string.' });
  } else if (obj.input.length < 1 || obj.input.length > MAX_INPUT_LENGTH) {
    errors.push({ field: 'input', message: `Must be 1 to ${MAX_INPUT_LENGTH} characters.` });
  } else if (obj.input.trim() === '') {
    errors.push({ field: 'input', message: 'Must not be only whitespace.' });
  } else {
    input = obj.input;
  }

  const steps = readInteger(obj, 'steps', 5, 1, 20, errors);
  const failAttempts = readInteger(obj, 'failAttempts', 0, 0, 5, errors);

  if (errors.length > 0) return { ok: false, fields: errors };
  return { ok: true, value: { input, steps, failAttempts } };
}

