  }

  const body = await readBody(req);
  if (body.tooLarge) {
    errors.push({ field: 'body', message: `Must be at most ${MAX_BODY_BYTES} bytes.` });
  } else {
    let parsed: unknown;
    let parsedOk = true;
    try {
      parsed = JSON.parse(body.text);
    } catch {
      parsedOk = false;
      errors.push({ field: 'body', message: 'Malformed JSON.' });
    }
    if (parsedOk) {
      const result = validateNewJob(parsed);
      if (result.ok) {
        if (errors.length === 0) return { ok: true, key, value: result.value };
      } else {
        errors.push(...result.fields);
      }
    }
  }
  return { ok: false, fields: errors };
}

function samePayload(row: JobRow, job: NewJob): boolean {
  return row.input === job.input && row.steps === job.steps && row.fail_attempts === job.failAttempts;
}

async function createJob(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const parsed = await parseCreateRequest(req);
  if (!parsed.ok) {
    sendError(res, 400, 'invalid_request', 'The request is invalid.', parsed.fields);
    return;
  }
  const { key, value } = parsed;

  const outcome = transaction(db, () => {
    if (key !== null) {
      const existing = findJobRowByKey(db, key);
      if (existing) return samePayload(existing, value) ? { kind: 'replay' as const, row: existing } : { kind: 'conflict' as const };
    }
    return { kind: 'created' as const, row: insertJobRow(db, value, key) };
  });

  if (outcome.kind === 'conflict') {
    sendError(res, 409, 'idempotency_conflict', 'This Idempotency-Key was already used with a different payload.');
  } else if (outcome.kind === 'replay') {
    sendJson(res, 200, toPublicJob(outcome.row));
  } else {
    sendJson(res, 201, toPublicJob(outcome.row));
  }
}

function health(res: ServerResponse): void {
  const heartbeat = db.prepare('SELECT seen_at FROM worker_heartbeat WHERE name = ?').get('worker') as
    | { seen_at: number }
    | undefined;
  const workerUp = heartbeat !== undefined && Date.now() - Number(heartbeat.seen_at) <= WORKER_FRESH_MS;
  sendJson(res, 200, { status: 'ok', worker: workerUp ? 'up' : 'down' });
}

async function route(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const method = req.method ?? 'GET';
  const { pathname } = new URL(req.url ?? '/', 'http://localhost');

  if (pathname === '/health') {
    if (method !== 'GET') return methodNotAllowed(res, ['GET']);
    return health(res);
  }

  if (pathname === '/') {
    if (method !== 'GET') return methodNotAllowed(res, ['GET']);
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
    res.end(uiHtml);
    return;
  }

  if (pathname === '/api/jobs') {
    if (method === 'GET') return sendJson(res, 200, { jobs: listJobRows(db).map(toPublicJob) });
    if (method === 'POST') return createJob(req, res);
    return methodNotAllowed(res, ['GET', 'POST']);
  }

  const match = /^\/api\/jobs\/([^/]+)$/.exec(pathname);
  if (match) {
    if (method !== 'GET') return methodNotAllowed(res, ['GET']);
    let id: string;
    try {
      id = decodeURIComponent(match[1]!);
    } catch {
      return notFound(res);
    }
    const row = getJobRow(db, id);
    if (!row) return sendError(res, 404, 'not_found', `No job with id ${id}.`);
    return sendJson(res, 200, toPublicJob(row));
  }

  notFound(res);
}

const server = createServer((req, res) => {
  route(req, res).catch((err: unknown) => {
    console.error('request failed:', err);
    if (!res.headersSent) sendError(res, 500, 'internal_error', 'Internal server error.');
    else res.end();
  });
});

const port = Number(process.env.PORT || 3000);
server.listen(port, () => console.log(`server listening on ${port}`));

function shutdown(): void {
  server.close(() => {
    db.close();
    process.exit(0);
  });
  server.closeAllConnections();
}

process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);

