import { setTimeout as sleep } from 'node:timers/promises';
import { openDatabase } from './db.ts';
import { MAX_ATTEMPTS, TRANSIENT_ERROR, type JobRow } from './jobs.ts';

const STEP_MS = 100;
const POLL_MS = 200;
const HEARTBEAT_MS = 1_000;
/** A running job's lease is renewed after every step. If the worker dies, the lease lapses and the job is requeued. */
const LEASE_MS = 3_000;
const RETRY_DELAY_MS = 500;

const db = openDatabase();
let stopping = false;

const nowIso = (): string => new Date().toISOString();

function writeHeartbeat(): void {
  try {
    db.prepare(
      'INSERT INTO worker_heartbeat (name, seen_at) VALUES (?, ?) ON CONFLICT(name) DO UPDATE SET seen_at = excluded.seen_at',
    ).run('worker', Date.now());
  } catch (err) {
    console.error('heartbeat failed:', err);
  }
}

/** Requeues jobs still marked running whose lease has lapsed, e.g. because a previous worker was killed. */
function recoverExpiredLeases(): void {
  const result = db
    .prepare(
      `UPDATE jobs SET status = 'queued', progress_completed = 0, lease_until = NULL, updated_at = ?
       WHERE status = 'running' AND (lease_until IS NULL OR lease_until < ?)`,
    )
    .run(nowIso(), Date.now());
  if (Number(result.changes) > 0) console.log(`requeued ${result.changes} job(s) left running by a previous worker`);
}

/** Atomically claims the oldest eligible queued job and starts a new attempt on it. */
function claimNext(): JobRow | undefined {
  const now = Date.now();
  return db
    .prepare(
      `UPDATE jobs SET status = 'running', attempts = attempts + 1, progress_completed = 0, lease_until = ?, updated_at = ?
       WHERE seq = (SELECT seq FROM jobs WHERE status = 'queued' AND run_after <= ? ORDER BY seq LIMIT 1)
       RETURNING *`,
    )
    .get(now + LEASE_MS, nowIso(), now) as unknown as JobRow | undefined;
}

/** Ends an attempt that was interrupted by shutdown. The attempt did not run, so the count is undone. */
function release(job: JobRow): void {
  db.prepare(
    `UPDATE jobs SET status = 'queued', attempts = attempts - 1, progress_completed = 0, lease_until = NULL, updated_at = ?
     WHERE id = ? AND status = 'running' AND attempts = ?`,
  ).run(nowIso(), job.id, job.attempts);
}

function failAttempt(job: JobRow): void {
  if (job.attempts >= MAX_ATTEMPTS) {
    db.prepare(
      `UPDATE jobs SET status = 'failed', error = ?, result = NULL, progress_completed = 0, lease_until = NULL, updated_at = ?
       WHERE id = ? AND status = 'running' AND attempts = ?`,
    ).run(TRANSIENT_ERROR, nowIso(), job.id, job.attempts);
    console.log(`job ${job.id} failed after ${job.attempts} attempts`);
  } else {
    db.prepare(
      `UPDATE jobs SET status = 'queued', run_after = ?, progress_completed = 0, lease_until = NULL, updated_at = ?
       WHERE id = ? AND status = 'running' AND attempts = ?`,
    ).run(Date.now() + RETRY_DELAY_MS, nowIso(), job.id, job.attempts);
    console.log(`job ${job.id} attempt ${job.attempts} failed transiently; retrying`);
  }
}

function complete(job: JobRow): void {
  db.prepare(
    `UPDATE jobs SET status = 'completed', progress_completed = steps, result = ?, error = NULL, lease_until = NULL, updated_at = ?
     WHERE id = ? AND status = 'running' AND attempts = ?`,
  ).run(job.input.toUpperCase(), nowIso(), job.id, job.attempts);
}

/** Runs one attempt step by step. Returns early if the lease was lost or shutdown was requested. */
async function runAttempt(job: JobRow): Promise<void> {
  const failing = job.attempts <= job.fail_attempts;
  for (let step = 1; step <= job.steps; step++) {
    await sleep(STEP_MS);
    if (stopping) {
      release(job);
      return;
    }
    if (failing && step === 1) {
      failAttempt(job);
      return;
    }
    const result = db
      .prepare(
        `UPDATE jobs SET progress_completed = ?, lease_until = ?, updated_at = ?
         WHERE id = ? AND status = 'running' AND attempts = ?`,
      )
      .run(step, Date.now() + LEASE_MS, nowIso(), job.id, job.attempts);
    if (Number(result.changes) === 0) return;
  }
  complete(job);
}

writeHeartbeat();
const heartbeatTimer = setInterval(writeHeartbeat, HEARTBEAT_MS);

for (const signal of ['SIGINT', 'SIGTERM'] as const) {
  process.on(signal, () => {
    stopping = true;
  });
}

console.log('worker started');
while (!stopping) {
  try {
    recoverExpiredLeases();
    const job = claimNext();
    if (job) {
      console.log(`job ${job.id} attempt ${job.attempts} started`);
      await runAttempt(job);
    } else {
      await sleep(POLL_MS);
    }
  } catch (err) {
    console.error('worker error:', err);
    await sleep(POLL_MS);
  }
}

clearInterval(heartbeatTimer);
try {
  db.prepare('DELETE FROM worker_heartbeat WHERE name = ?').run('worker');
} catch {
  // the database may be unavailable; the heartbeat goes stale anyway
}
db.close();
console.log('worker stopped');

